<script setup lang="ts">
/**
 * A list beside the selected item's detail (`design/archetypes/master-detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/master-detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import { afterRender, masterDetailFocus, masterDetailHolds, useTrackedSlots } from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/master-detail-page.module.css'
import Button from '../controls/Button.vue'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState.vue'
import PageHeader from '../structure/PageHeader.vue'
import SplitPane from '../layout/SplitPane.vue'

export interface MasterDetailPageProps {
  /**
   * The way back to the list while the detail is drawn alone.
   */
  backLabel: string
  description?: string
  /**
   * The detail pane while nothing is selected, in the split. Required so the page always decides
   * it.
   */
  emptyState: EmptyStateProps
  /**
   * Names the list pane's region and the split's separator.
   */
  listLabel: string
  title: string
}

defineOptions({ name: 'MasterDetailPage', inheritAttrs: false })

defineProps<MasterDetailPageProps>()
const emit = defineEmits<{ back: [] }>()
const callerSlots = defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  detail?: (props: Record<string, never>) => unknown
  list: (props: Record<string, never>) => unknown
}>()
const slots = useTrackedSlots(callerSlots)
const narrow = ref(false)
const held = ref(false)
const selected = ref(false)
const body = useTemplateRef<HTMLElement>('body')
const root = useTemplateRef<HTMLElement>('root')
const measure = computed(() => () => {
  if (root.value === null) return
  const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
  narrow.value = root.value.getBoundingClientRect().width < 48 * rem
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    measure.value()
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [root.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  selected.value = Boolean(slots.detail)
}
onMounted(effect2)
watch(() => Boolean(slots.detail), effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const listener = ($event: DocumentEventMap['focusin']) => {
    held.value = masterDetailHolds(body.value, $event)
  }
  document.addEventListener('focusin', listener)
  release3 = () => document.removeEventListener('focusin', listener)
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
const effect4 = () => {
  afterRender(() => masterDetailFocus(body.value, held.value))
}
watch(
  () =>
    narrow.value ? (selected.value ? 'detail' : 'list') : selected.value ? 'split-detail' : 'split',
  effect4,
  { flush: 'post' },
)
</script>

<template>
  <div
    ref="root"
    :class="styles.page"
    :data-layout="narrow ? 'single' : 'split'"
    :data-pane="narrow ? (selected ? 'detail' : 'list') : undefined"
    data-member="master-detail-page"
  >
    <PageHeader :title="title" :description="description">
      <template v-if="$slots.actions" #actions>
        <slot name="actions" />
      </template>
    </PageHeader>
    <!-- body -->
    <div ref="body" :class="styles.body">
      <template v-if="narrow">
        <!-- list -->
        <section
          :class="styles.list"
          :aria-label="listLabel"
          tabindex="-1"
          :hidden="selected"
          data-master-detail-page-part="list"
        >
          <slot name="list" />
        </section>
        <!-- detail -->
        <div v-if="selected" :class="styles.detail" data-master-detail-page-part="detail">
          <!-- back -->
          <div :class="styles.back" data-master-detail-page-part="back">
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="back"
              :label="backLabel"
              @click="emit('back')"
            />
          </div>
          <!-- scroll -->
          <div :class="styles.scroll">
            <slot name="detail" />
          </div>
        </div>
      </template>
      <SplitPane v-else :label="listLabel" :defaultRatio="0.32" :startMin="240" :endMin="420">
        <template #start>
          <!-- list -->
          <section
            :class="styles.list"
            :aria-label="listLabel"
            tabindex="-1"
            data-master-detail-page-part="list"
          >
            <slot name="list" />
          </section>
        </template>
        <template #end>
          <!-- detail -->
          <div :class="styles.detail" data-master-detail-page-part="detail">
            <!-- scroll -->
            <div v-if="selected" :class="styles.scroll">
              <slot name="detail" />
            </div>
            <!-- empty -->
            <div v-else :class="styles.empty">
              <EmptyState
                :icon="emptyState.icon"
                :title="emptyState.title"
                :description="emptyState.description"
              >
                <template v-if="emptyState.action !== undefined" #action>
                  <component :is="emptyState.action" />
                </template>
                <template v-if="emptyState.secondaryAction !== undefined" #secondaryAction>
                  <component :is="emptyState.secondaryAction" />
                </template>
              </EmptyState>
            </div>
          </div>
        </template>
      </SplitPane>
    </div>
  </div>
</template>
